    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #121a2f;
        --panel-strong: #18233d;
        --text: #f5f7fb;
        --muted: #c9d3e6;
        --accent: #8bd3ff;
        --accent-strong: #b6e4ff;
        --border: #52617a;
        --button: #d7f0ff;
        --button-text: #07111f;
        --button-hover: #ffffff;
        --shadow: #020617;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #1f3a5f 0, transparent 34rem),
          linear-gradient(135deg, var(--bg), #050813 72%);
        line-height: 1.5;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.65rem 0.9rem;
        color: var(--button-text);
        background: var(--button);
        border-radius: 999px;
        transform: translateY(-160%);
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--accent);
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 30rem);
        padding: clamp(1.25rem, 5vw, 2rem);
        background: var(--panel);
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        box-shadow: 0 1.5rem 4rem var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.85rem, 7vw, 2.5rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0.85rem 0 1.5rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
        padding: 1rem;
        background: var(--panel-strong);
        border: 1px solid var(--border);
        border-radius: 0.9rem;
      }

      .checkbox-label {
        display: grid;
        grid-template-columns: 1.25rem 1fr;
        gap: 0.75rem;
        align-items: start;
        font-weight: 700;
      }

      input[type="checkbox"] {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.15rem 0 0;
        color: var(--accent);
        background: var(--bg);
        border: 2px solid var(--border);
        border-radius: 0.3rem;
        accent-color: var(--accent);
        cursor: pointer;
      }

      input[type="checkbox"]:focus-visible,
      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--accent);
      }

      .required {
        color: var(--accent-strong);
        font-weight: 800;
      }

      .helper-text {
        margin: 0 0 0 2rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      button {
        width: 100%;
        padding: 0.85rem 1rem;
        color: var(--button-text);
        background: var(--button);
        border: 2px solid var(--button);
        border-radius: 999px;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition: background-color 160ms ease, border-color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: var(--button-hover);
        border-color: var(--button-hover);
      }

      button:active {
        transform: translateY(1px);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--accent-strong);
        font-weight: 700;
      }

      @media (max-width: 22rem) {
        main {
          padding-inline: 0.75rem;
        }

        .form-field {
          padding: 0.85rem;
        }
      }

      @media (forced-colors: active) {
        body,
        .card,
        .form-field {
          color: CanvasText;
          background: Canvas;
          border-color: ButtonBorder;
        }

        .eyebrow,
        .intro,
        .helper-text,
        .required,
        .status {
          color: CanvasText;
        }

        button,
        .skip-link {
          color: ButtonText;
          background: ButtonFace;
          border-color: ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main">
      <div id="root"></div>
    </main>

    <script>
      const createElement = (template) => {
        const wrapper = document.createElement("div");
        wrapper.innerHTML = template.trim();
        return wrapper.firstElementChild;
      };

      function ConsentForm() {
        return createElement(`
          <section class="card" aria-labelledby="form-title">
            <p class="eyebrow">Account setup</p>
            <h1 id="form-title">Review terms</h1>
            <p class="intro">
              Confirm your agreement before continuing.
            </p>
            <form id="terms-form" novalidate>
              <div class="form-field">
                <label class="checkbox-label" for="terms-consent">
                  <input
                    id="terms-consent"
                    name="termsConsent"
                    type="checkbox"
                    required
                    aria-describedby="terms-helper"
                  >
                  <span>I agree to the terms of use <span class="required" aria-hidden="true">*</span></span>
                </label>
                <p class="helper-text" id="terms-helper">
                  Required to create or continue using your account.
                </p>
              </div>
              <button type="submit">Submit agreement</button>
              <p class="status" id="form-status" aria-live="polite"></p>
            </form>
          </section>
        `);
      }

      function App() {
        return ConsentForm();
      }

      const root = document.querySelector("#root");
      root.append(App());

      const form = document.querySelector("#terms-form");
      const checkbox = document.querySelector("#terms-consent");
      const status = document.querySelector("#form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          status.textContent = "Please agree to the terms of use before submitting.";
          checkbox.focus();
          return;
        }

        status.textContent = "Thanks. Your agreement has been recorded.";
        form.reset();
      });
    </script>
  </body>
</html>
