        --panel-strong: #18233d;
        --text: #f5f7fb;
        --muted: #c9d3e6;
        --accent: #8bd3ff;
        --accent-strong: #b6e4ff;
        --border: #52617a;
        --button: #d7f0ff;
        --button-text: #07111f;
        --button-hover: #ffffff;
        --shadow: #020617;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
